{"content": "<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>直角车间 — 按图加工，尺寸说话</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Karla:wght@400;500;700&family=Newsreader:opsz,wght@6..72,400;6..72,500&family=Noto+Sans+SC:wght@400;500;700&family=Noto+Serif+SC:wght@400;500&display=swap">
<style>
/* ============================================================
   直角车间 · 单文件页
   尺寸链三件可测值：栏宽 132px ／ 端点短线 1×9px ／ 断口 12px
   读数＝该块实际行数（正文一行 24px）；总 84 → 块 102 → 组 120，逐级内移 18px
   本页 61 行 = 15 + 9 + 8 + 7 + 6 + 11 + 5
   ============================================================ */

:root{
  /* 配色：只用这五个值 */
  --paper:#E8E3D9;
  --ink:#1F2A2E;
  --ink-soft:#7A8C8E;
  --paper-deep:#3C4A4D;
  --accent:#C9A227;

  /* 字体两条链 */
  --head:Karla,"Noto Sans SC";
  --body:Newsreader,"Noto Serif SC","Songti SC";

  /* 一行 */
  --u:24px;

  /* 尺寸链几何 */
  --chain-w:132px;                       /* 左侧尺寸链栏宽 */
  --ext-len:6px;                         /* 每块上下沿引出的延长线 */
  --tick-len:9px;                        /* 端点短线 1px × 9px */
  --gap:12px;                            /* 尺寸线正中断口 */
  --step:18px;                           /* 分段逐级内移 */
  --lv2:calc(var(--chain-w) - var(--gap));   /* 120px 组尺寸（最内一级） */
  --lv1:calc(var(--lv2) - var(--step));      /* 102px 块尺寸 */
  --lv0:calc(var(--lv1) - var(--step));      /* 84px 总尺寸（最外侧） */

  /* 线宽只有 1px 与 2px */
  --lw1:1px;
  --lw2:2px;
}

*{box-sizing:border-box;margin:0;padding:0;border-radius:0}
html{-webkit-text-size-adjust:100%}
body{
  background:var(--paper);
  color:var(--ink);
  font-family:var(--body);
  font-size:15px;
  line-height:var(--u);
  padding-bottom:72px;
}
img{display:block;border-radius:0}
a{border-radius:0}
/* 无阴影、无圆角：全站只有直角边界与 1px / 2px 线宽差 */

