/* 端点短线 1×9px：跨在延长线端头上，两端各一枚 */
.tick{position:absolute;left:0;width:var(--tick);height:var(--tick-h);background:var(--ink)}
/* 6px 延长线（2px 线宽）：自块的上下沿横向引出 */
.ext{position:absolute;width:var(--ext);height:var(--r2);background:var(--ink)}
/* 断口：12px，居中；断口里竖排这一块的行数 */
.rd{position:absolute;left:calc(var(--notch) / -2);top:50%;transform:translateY(-50%);
    width:var(--notch);background:var(--paper);display:flex;align-items:center;justify-content:center;z-index:2}
.rd b{writing-mode:vertical-rl;text-orientation:upright;font:700 12px/1 var(--f-t);letter-spacing:0}
/* 每块自己的尺寸：延长线就在本块的上下沿 */
.blk-dim .ext.t{top:calc(var(--tick-h) / -2 + 1px)}
.blk-dim .ext.b{bottom:calc(var(--tick-h) / -2 + 1px)}
.blk-dim .tick.t{top:calc(var(--tick-h) / -2)}
.blk-dim .tick.b{bottom:calc(var(--tick-h) / -2)}
.blk-dim .rule{top:5px;bottom:5px}
.blk-dim .rd{height:calc(var(--notch) + 34px)}
/* 总尺寸 / 分段尺寸：延长线自它们所辖范围的首尾块边缘一直拉到本档位置 */
.tot-dim .ext,.seg-dim .ext{height:var(--r2)}
.tot-dim .ext{left:var(--x0);width:calc(-1 * var(--x0))}
.seg-dim .ext{left:var(--x1);width:calc(-1 * var(--x1))}
.tot-dim .rule,.seg-dim .rule{top:5px;bottom:5px}
.tot-dim .rd,.seg-dim .rd{height:calc(var(--notch) + 20px)}
.tot-dim .rd b{font-size:var(--s6)}
/* 链的抬头：说明这套读数的单位 */
.chain-cap{position:absolute;left:2px;top:0;width:0;height:0;pointer-events:none}
.chain-cap b{position:absolute;left:0;top:0;writing-mode:vertical-rl;text-orientation:upright;
  font:700 var(--s7)/1 var(--f-t);letter-spacing:.22em;color:var(--ink-soft)}
.chain-cap u{position:absolute;left:-1px;top:-14px;width:var(--r2);height:8px;background:var(--accent);text-decoration:none}

