content.content:
1	<!DOCTYPE html>
2	<html lang="zh-CN">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width,initial-scale=1">
6	<title>直角车间 — 按图加工，公差不猜</title>
7	<link rel="preconnect" href="https://fonts.googleapis.com">
8	<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
9	<link href="https://fonts.googleapis.com/css2?family=Karla:wght@400;700&family=Newsreader:opsz,wght@6..72,400;6..72,700&family=Noto+Sans+SC:wght@400;700&family=Noto+Serif+SC:wght@400;700&display=swap" rel="stylesheet">
10	<style>
11	/* ==========================================================================
12	   直角车间 · 单页施工图
13	   骨架：左侧 132px 空白里挂一条尺寸链。
14	     每块内容的上下沿各横向引出一条 6px 延长线（2px 线宽）；
15	     两条延长线之间是一条 1px 尺寸线；
16	     尺寸线两端各一枚 1×9px 的端点短线；
17	     正中留 12px 断口，断口里竖排这一块的行数（正文 24px 一行）；
18	     总尺寸记在最外侧，分段尺寸按 18px 逐级内移。
19	   读序：总行数 → 分段行数 → 块里的字。
20	   ========================================================================== */
21	:root{
22	  --paper:#E8E3D9;      /* 底：铺最大面积 */
23	  --ink:#1F2A2E;        /* 字与结构线 */
24	  --ink-soft:#7A8C8E;   /* 次级线 */
25	  --paper-deep:#3C4A4D; /* 次级字 */
26	  --accent:#C9A227;     /* 只做点、线、小块 */
27	
28	  --chain:132px;   /* 尺寸链栏宽（可测值 1） */
29	  --ext:6px;       /* 延长线长 */
30	  --tick:1px;      /* 端点短线宽 */
31	  --tick-h:9px;    /* 端点短线高（可测值 2：1×9px） */
32	  --notch:12px;    /* 断口（可测值 3） */
33	  --step:18px;     /* 分段尺寸逐级内移 */
34	  --line-h:24px;   /* 正文一行 = 读数一行 */
35	
36	  --r1:1px;--r2:2px;                 /* 全站只有这两级线宽 */
37	  --x2:calc(-1 * var(--ext));                        /* 每块：-6px  */
38	  --x1:calc(-1 * (var(--ext) + var(--step)));        /* 分段：-24px */
39	  --x0:calc(-1 * (var(--ext) + var(--step) * 2));    /* 总尺寸：-42px */
40	
41	  --f-t:Karla,"Noto Sans SC",sans-serif;
42	  --f-b:Newsreader,"Noto Serif SC","Songti SC",serif;
43	
44	  --s1:93px;   /* 最大档 = 正文 15px 的 6.2 倍 */
45	  --s2:46px;--s3:30px;--s4:20px;--s5:15px;--s6:13px;--s7:11px;
46	}
47	*{margin:0;padding:0;box-sizing:border-box;border-radius:0}
48	html{-webkit-text-size-adjust:100%}
49	body{background:var(--paper);color:var(--ink);font-family:var(--f-b);font-size:var(--s5);line-height:var(--line-h)}
50	h1,h2,h3,h4,th,.f-t,.btn,.no,.st,.m,dt,.cap,.u{font-family:var(--f-t);font-weight:700}
51	img{display:block;border:0;border-radius:0}
52	a{color:inherit;text-decoration:none;border-radius:0}
53	button{font:inherit;border:0;background:none;border-radius:0}
54	
55	/* ---------- 页栏：内容自 132px 之后起排，链挂在左边空白里 ---------- */
56	.wrap{max-width:1280px;margin:0 auto;padding-left:var(--chain)}
57	.sec{padding-right:30px}
58	.stack{position:relative}
59	
60	/* ---------- 块：高度 = 行数 × 24px，读数就是从这里来的 ---------- */
61	.blk{position:relative;height:calc(var(--rows) * var(--line-h));border-top:var(--r1) solid var(--ink)}
62	.blk:first-child{border-top:0}
63	.b1{--rows:2}.b2{--rows:6}.b3{--rows:7}.b4{--rows:9}.b5{--rows:5}.b6{--rows:4}.b7{--rows:3}
64	
65	/* ---------- 尺寸链 ---------- */
66	.dim{position:absolute;pointer-events:none}
67	.dim.blk-dim{top:0;bottom:0;left:var(--x2);width:0}
68	.dim.seg-dim,.dim.tot-dim{left:0;width:0;top:0;bottom:0}
69	/* 1px 尺寸线：两端各让出 9px 给端点短线，正中留 12px 断口 */
70	.rule{position:absolute;left:0;width:var(--r1)}
71	.rule::before,.rule::after{content:"";position:absolute;left:0;width:var(--r1);background:var(--ink)}
72	.rule::before{top:0;height:calc(50% - var(--notch) / 2)}
73	.rule::after{bottom:0;height:calc(50% - var(--notch) / 2)}
74	/* 端点短线 1×9px：跨在链线上，两端各一枚 */
75	.tick{position:absolute;width:var(--tick);height:var(--tick-h);background:var(--ink)}
76	/* 6px 延长线（2px 线宽）：自块的上下沿横向引出 */
77	.ext{position:absolute;width:var(--ext);height:var(--r2);background:var(--ink)}
78	/* 断口：12px，居中；断口里竖排这一块的行数 */
79	.rd{position:absolute;top:50%;transform:translateY(-50%);
80	    width:var(--notch);background:var(--paper);display:flex;align-items:center;justify-content:center;z-index:2}
81	.rd b{writing-mode:vertical-rl;text-orientation:upright;font:700 12px/1 var(--f-t);letter-spacing:0}
82	/* 每块自己的尺寸：延长线就在本块的上下沿，链线贴在本块左沿 6px 处 */
