file.content:
/* ---------- 块：高度 = 行数 × 24px，读数就是从这里来的 ---------- */
.blk{position:relative;height:calc(var(--rows) * var(--line-h));border-top:var(--r1) solid var(--ink)}
.blk:first-child{border-top:0}
.b1{--rows:2}.b2{--rows:6}.b3{--rows:7}.b4{--rows:9}.b5{--rows:5}.b6{--rows:4}.b7{--rows:3}

/* ---------- 尺寸链 ---------- */
.dim{position:absolute;pointer-events:none}
.dim.blk-dim{top:0;bottom:0;left:var(--x2);width:0}
.dim.seg-dim,.dim.tot-dim{left:0;width:0;top:0;bottom:0}
/* 1px 尺寸线：两端各让出 9px 给端点短线，正中留 12px 断口 */
.rule{position:absolute;left:0;width:var(--r1)}
.rule::before,.rule::after{content:"";position:absolute;left:0;width:var(--r1);background:var(--ink)}
.rule::before{top:0;height:calc(50% - var(--notch) / 2)}
.rule::after{bottom:0;height:calc(50% - var(--notch) / 2)}
/* 端点短线 1×9px：跨在链线上，两端各一枚 */
.tick{position:absolute;width:var(--tick);height:var(--tick-h);background:var(--ink)}
/* 6px 延长线（2px 线宽）：自块的上下沿横向引出 */
.ext{position:absolute;width:var(--ext);height:var(--r2);background:var(--ink)}
/* 断口：12px，居中；断口里竖排这一块的行数 */
.rd{position:absolute;top:50%;transform:translateY(-50%);
    width:var(--notch);background:var(--paper);display:flex;align-items:center;justify-content:center;z-index:2}
.rd b{writing-mode:vertical-rl;text-orientation:upright;font:700 12px/1 var(--f-t);letter-spacing:0}
/* 每块自己的尺寸：延长线就压在本块的上下沿，链线贴在本块左沿 6px 处 */
.blk-dim .ext.t{top:0}
.blk-dim .ext.b{bottom:0}
.blk-dim .tick{left:0}
.blk-dim .tick.t{top:calc((var(--r2) - var(--tick-h)) / 2)}
.blk-dim .tick.b{bottom:calc((var(--r2) - var(--tick-h)) / 2)}
.blk-dim .rule{left:0;top:var(--rule-in);bottom:var(--rule-in)}
.blk-dim .rd{left:calc(var(--notch) / -2);height:calc(var(--notch) + 34px)}
/* 总尺寸 / 分段尺寸：延长线自它们所辖范围的首尾块边缘一直拉到本档位置 */
.tot-dim .ext,.seg-dim .ext{height:var(--r2);top:0}
.tot-dim .ext.b,.seg-dim .ext.b{top:auto;bottom:0}
.tot-dim .ext{left:var(--x0);width:calc(-1 * var(--x0))}
.seg-dim .ext{left:var(--x1);width:calc(-1 * var(--x1))}
.tot-dim .rule{left:var(--x0);top:var(--rule-in);bottom:var(--rule-in)}
.seg-dim .rule{left:var(--x1);top:var(--rule-in);bottom:var(--rule-in)}
.tot-dim .tick{left:var(--x0)}
.seg-dim .tick{left:var(--x1)}
.tot-dim .tick.t,.seg-dim .tick.t{top:calc((var(--r2) - var(--tick-h)) / 2)}
.tot-dim .tick.b,.seg-dim .tick.b{bottom:calc((var(--r2) - var(--tick-h)) / 2)}
.tot-dim .rd{left:calc(var(--x0) - var(--notch) / 2);height:calc(var(--notch) + 28px)}
.seg-dim .rd{left:calc(var(--x1) - var(--notch) / 2);height:calc(var(--notch) + 28px)}
.tot-dim .rd b,.seg-dim .rd b{font-size:var(--s6)}
/* 链的抬头：说明这条链量的是什么 */
.chain-cap{position:absolute;left:calc(-1 * var(--chain) + 12px);top:14px;height:130px;width:0;
  display:flex;flex-direction:column;align-items:center;pointer-events:none}
.chain-cap b{writing-mode:vertical-rl;text-orientation:upright;
  font:700 var(--s7)/1 var(--f-t);letter-spacing:.22em;color:var(--ink-soft)}
.chain-cap u{display:block;width:var(--r2);height:8px;background:var(--accent);border:0;text-decoration:none;margin-top:10px}

